'.me-Design--neon .me-Btn--primary:hover { background: var(--me-accent); color: var(--me-on-accent) !important; filter: none; }',
'',
'/* Glitch: a jittering, colour-split code */',
'.me-Design--glitch .me-Code { color: #ffffff !important; text-shadow: -3px 0 var(--me-accent), 3px 0 var(--me-accent-2); }',
'.me-Design--glitch.me-Anim--art .me-Code { animation: me-glitch 2.6s steps(1) infinite; }',
