'.me-Design--terminal .me-Stage { padding-top: 3.5rem; border: 1px solid var(--me-border); text-align: start; font-family: var(--me-mono);',
'                                 box-shadow: 0 30px 80px -24px color-mix(in srgb, var(--me-accent) 30%, transparent); }',
'.me-Design--terminal .me-Stage::before { content: ""; position: absolute; top: 1.05rem; inset-inline-start: 1.25rem; width: .7rem; height: .7rem; border-radius: 50%;',
'                                         background: #ff5f56; box-shadow: 1.1rem 0 #ffbd2e, 2.2rem 0 #27c93f; }',
'.me-Design--terminal .me-Stage::after { content: ""; position: absolute; top: 2.75rem; inset-inline: 0; height: 1px; background: var(--me-border); }',
'.me-Design--terminal .me-Artbox { display: none !important; }',
'.me-Design--terminal :is(.me-Code, .me-Title, .me-Text, .me-Btn, .me-Tech, .me-Home, .me-Links) { font-family: var(--me-mono); }',
'.me-Design--terminal .me-Code { padding: 0; background: none; color: var(--me-accent); letter-spacing: 0; }',
