'.me-Design--terminal .me-Title::after { content: ""; display: inline-block; width: .55em; height: 1.05em; margin-inline-start: .25em; vertical-align: -.15em; background: var(--me-accent); animation: me-blink 1.1s steps(1) infinite; }',
'.me-Design--terminal .me-Actions, .me-Design--terminal .me-Links { justify-content: flex-start; }',
'.me-Design--terminal .me-Btn { background: transparent; border-color: var(--me-border); }',
'.me-Design--terminal .me-Btn--primary { color: var(--me-accent) !important; border: 1px solid var(--me-accent); box-shadow: 0 0 18px -6px var(--me-accent); text-transform: uppercase; letter-spacing: .1em; }',
'.me-Design--terminal .me-Btn--primary:hover { background: var(--me-accent); color: var(--me-on-accent) !important; filter: none; }',
'',
'/* Editorial: paper, serif, fine rules */',
'.me-Design--editorial .me-Stage { border: 1px solid var(--me-border); box-shadow: 0 30px 60px -30px rgba(43, 27, 22, .35); }',
'.me-Design--editorial .me-Stage::before { content: ""; position: absolute; inset: 8px; border: 1px solid var(--me-border); pointer-events: none; }',
'.me-Design--editorial .me-Code { font-family: var(--me-serif); font-style: italic; font-weight: 400; color: var(--me-accent) !important; }',
'.me-Design--editorial .me-Title { font-family: var(--me-serif); font-style: italic; font-weight: 600; }',
'.me-Design--editorial .me-Title::after { content: ""; display: block; width: 3rem; height: 2px; margin: 1rem auto 0; background: var(--me-accent); }',
'.me-Design--editorial .me-Btn { text-transform: uppercase; letter-spacing: .14em; font-size: .75rem; }',
'.me-Design--editorial .me-Btn--primary { background: var(--me-accent); box-shadow: none; }',
'',
'/* Soft UI: an embossed code on a raised card */',
'.me-Design--soft .me-Code { color: var(--me-bg) !important; text-shadow: 6px 6px 12px var(--me-soft-dark), -6px -6px 12px var(--me-soft-light); }',
'.me-Design--soft .me-Btn { border: 0; box-shadow: 6px 6px 14px var(--me-soft-dark), -6px -6px 14px var(--me-soft-light); background: var(--me-bg); }',
'.me-Design--soft .me-Btn--primary { background: linear-gradient(135deg, var(--me-accent), var(--me-accent-2)); }',
'',
'/* Bold: ink outlines, hard shadows, a sticker code */',
'.me-Design--bold .me-Stage { border: 3px solid var(--me-ink); }',
'.me-Design--bold .me-Code { padding: .5rem 1.25rem; border: 3px solid var(--me-ink); border-radius: 12px; background: var(--me-accent-2); color: var(--me-ink) !important;',
'                            font-size: clamp(2.5rem, 2rem + 3vw, 4rem); font-weight: 900; letter-spacing: -.02em; transform: rotate(-4deg); box-shadow: 5px 5px 0 var(--me-ink); }',
'.me-Design--bold .me-Btn { border: 2px solid var(--me-ink); box-shadow: 4px 4px 0 var(--me-ink); font-weight: 800; }',
'.me-Design--bold .me-Btn:hover { transform: translate(-2px, -2px); box-shadow: 6px 6px 0 var(--me-ink); }',
'.me-Design--bold .me-Btn--primary { background: var(--me-accent); }',
'.me-Design--bold .me-Title { font-weight: 900; }',
'',
'/* Space: stars, a planet, a floating illustration */',
'.me-Page.me-Design--space .me-Code { background-image: linear-gradient(180deg, #ffffff, var(--me-accent-2)); -webkit-background-clip: text; background-clip: text; color: transparent !important; }',
'.me-Design--space .me-Stage:has(.me-Code) .me-Artbox { display: block; }',
'.me-Design--space .me-Art { width: min(9rem, 45%); --me-art-fill: linear-gradient(135deg, #ffffff, var(--me-accent-2)); }',
