'<style id="me-css-2">',
'/* Blueprint: a technical drawing on blue grid paper */',
'.me-Design--blueprint .me-Stage { border: 1.5px dashed var(--me-border); box-shadow: none; }',
'.me-Design--blueprint .me-Stage::before { content: "FIG. 1"; position: absolute; top: .75rem; inset-inline-start: 1rem; color: var(--me-muted); font: 600 .6875rem var(--me-mono); letter-spacing: .12em; }',
'.me-Design--blueprint :is(.me-Code, .me-Text, .me-Btn) { font-family: var(--me-mono); }',
'.me-Design--blueprint .me-Code { background: transparent; border: 1px solid var(--me-border); border-radius: 2px; color: #ffffff !important; }',
'.me-Design--blueprint .me-Btn { background: transparent; border-color: var(--me-border); color: #ffffff !important; }',
'.me-Design--blueprint .me-Btn--primary { background: #ffffff; color: var(--me-accent) !important; box-shadow: none; }',
'.me-Design--blueprint .me-Links a { color: #ffffff; }',
'',
'/* Wave: a coloured band with a wave edge; the card sits over it */',
'.me-Design--wave .me-Main { align-items: flex-start; padding-top: max(13vh, 4rem); }',
'',
'/* phones */',
'@media (max-width: 600px) {',
'  .me-Stage { padding: 1.75rem 1.25rem; }',
'  .me-Actions { flex-direction: column; }',
'  .me-Actions .me-Btn { width: 100%; }',
'  .me-Design--wave .me-Bg::before { height: max(30vh, 12rem); }',
'  .me-Design--wave .me-Main { padding-top: max(8vh, 3rem); }',
'}',
'',
'/* motion */',
'@keyframes me-rise { from { opacity: 0; transform: translateY(16px) scale(.985); } to { opacity: 1; transform: none; } }',
'@keyframes me-float { 0%, 100% { transform: translateY(0); } 50% { transform: translateY(-10px); } }',
'@keyframes me-blink { 50% { opacity: 0; } }',
'@keyframes me-flicker { 0%, 18%, 22%, 25%, 53%, 57%, 100% { opacity: 1; } 20%, 24%, 55% { opacity: .35; } }',
'@keyframes me-glitch {',
'  0% { transform: none; } 12% { transform: translate(-3px, 1px) skewX(-4deg); text-shadow: -5px 0 var(--me-accent), 4px 0 var(--me-accent-2); }',
'  14% { transform: none; } 47% { transform: translate(3px, -2px); clip-path: inset(20% 0 45% 0); } 49% { transform: none; clip-path: none; }',
'  78% { transform: translate(-2px, 0) skewX(6deg); text-shadow: 5px 0 var(--me-accent), -4px 0 var(--me-accent-2); } 80% { transform: none; }',
'}',
'.me-Anim--entrance .me-Stage { animation: me-rise .7s cubic-bezier(.2, .8, .2, 1) both; }',
'.me-Anim--art .me-Art { animation: me-float 5s ease-in-out infinite; }',
'@media (prefers-reduced-motion: reduce) {',
'  .me-Page *, .me-Page *::before, .me-Page *::after { animation-duration: .01ms !important; animation-iteration-count: 1 !important; transition: none !important; }',
'}',
'@media (forced-colors: active) {',
'  .me-Bg { display: none; }',
'  .me-Stage { border: 1px solid CanvasText; }',
'  .me-Art { background: CanvasText; }',
'}',
'</style>',
'  #THEME_STYLE_CSS#',
'  #APPLICATION_CSS#',
'  #PAGE_CSS#',
'  #FAVICONS#',
'  #HEAD#',
'  <meta name="viewport" content="width=device-width, initial-scale=1.0, viewport-fit=cover" />',
'</head>',
'<body class="me-Page #PAGE_CSS_CLASSES#" #TEXT_DIRECTION# #ONLOAD#>',
'<script>',
'/* Modern Error: the Error Page Studio designer previews a look through the URL hash (#me=me-Design--neon ...) */',
'window.modernError = (function (body) {',
'  var LOOK = /^me-(Design|Art|Accent|Scheme|Bg|Width|Anim|Fx)-/;',
'  function applyPreview() {',
'    var m = /[#&]me=([^&]*)/.exec(window.location.hash);',
'    if (!m) { return; }',
'    Array.prototype.slice.call(body.classList).forEach(function (c) { if (LOOK.test(c)) { body.classList.remove(c); } });',
'    decodeURIComponent(m[1]).split(/[\s,]+/).forEach(function (c) { if (LOOK.test(c)) { body.classList.add(c); } });',
'  }',
'  try { applyPreview(); } catch (e) { /* never block an error page */ }',
'  return { applyPreview: applyPreview };',
'})(document.body);',
'</script>',
'<noscript class="t-PageBody-noScript">&APP_TEXT$APEX_PAGE_NOSCRIPT.</noscript>',
'#FORM_OPEN#',
'<div class="me-Bg" aria-hidden="true"><div class="me-Bg-media">#BACKGROUND_IMAGE#</div></div>'))
