,p_error_page_template=>wwv_flow_string.join(wwv_flow_t_varchar2(
'<div class="me-Error">',
'  <p class="me-Code">Oops</p>',
'  <h1 class="me-Title">#MESSAGE#</h1>',
'  <p class="me-Text">#ADDITIONAL_INFO#</p>',
'  <pre class="me-Tech">#TECHNICAL_INFO#</pre>',
'  <div class="me-Actions"><button type="button" class="me-Btn me-Btn--primary me-Back">#OK#</button></div>',
'  <a class="me-Home" href="&HOME_LINK.">#RETURN_TO_APPLICATION#</a>',
'</div>'))
,p_grid_type=>'FIXED'
,p_grid_max_columns=>12
,p_grid_always_use_max_columns=>true
,p_grid_has_column_span=>true
,p_grid_always_emit=>true
,p_grid_emit_empty_leading_cols=>true
,p_grid_emit_empty_trail_cols=>false
,p_grid_default_label_col_span=>2
,p_grid_template=>wwv_flow_string.join(wwv_flow_t_varchar2(
'<div class="container">',
'#ROWS#',
'</div>'))
,p_grid_row_template=>wwv_flow_string.join(wwv_flow_t_varchar2(
'<div class="row #CSS_CLASSES#">',
'#COLUMNS#',
'</div>'))
,p_grid_column_template=>'<div class="col col-#COLUMN_SPAN_NUMBER# #CSS_CLASSES# #FIRST_LAST_COLUMN_ATTRIBUTES#" #ATTRIBUTES#>#CONTENT#</div>'
,p_grid_first_column_attributes=>'col-start'
,p_grid_last_column_attributes=>'col-end'
,p_template_comment=>'Modern Error (Error Page Studio) - for APEX''s own error page (set it as the theme''s Error Page template; its Default Template Options choose the look) and for your own public error pages (404, access denied, session expired, maintenance, offline). Lo'
||'oks are template options - Design, Illustration, Accent Color, Color Scheme, Background. Slots - Content Body (your message; helper classes me-Code, me-Title, me-Text, me-Actions, me-Btn, me-Btn--primary, me-Back (go back), me-Reload (try again), me-'
||'Links), Top Bar (logo), Page Footer, Background Image. Optional text message MODERN_ERROR.COPY.'
);
